import java.util.*;
import java.io.*;

public class Variant3 {
    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        long lmao = scanner.nextLong();
        if (lmao >= N) {
            System.out.println(0);
        } else {
            int K = (int) lmao;
            int C = N - K;
            long[] factorials = new long[200001];
            long[] invFactorials = new long[200001];
            factorials[0] = 1;
            invFactorials[0] = 1;
            for (int i = 1; i <= 200000; i++) {
                factorials[i] = (factorials[i - 1] * i) % 998244353L;
                invFactorials[i] = fastExp(factorials[i], 998244353L - 2, 998244353L);
            }
            long result = powerMod(C, N, 998244353L);
            for (int e = 1; e < C; e++) {
                long temp = powerMod(C - e, N, 998244353L);
                temp = (temp * nCr(e, C, factorials, invFactorials)) % 998244353L;
                if (e % 2 == 1)
                    result = (result - temp + 998244353L) % 998244353L;
                else
                    result = (result + temp) % 998244353L;
            }
            result = (result * nCr(C, N, factorials, invFactorials)) % 998244353L;
            if (K > 0)
                result = (2 * result) % 998244353L;
            System.out.println(result);
        }
        scanner.close();
    }

    static long nCr(int a, int b, long[] fact, long[] invFact) {
        return (((fact[b] * invFact[a]) % 998244353L) * invFact[b - a]) % 998244353L;
    }

    static long powerMod(long base, int exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long fastExp(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
